        type: 'file',
        language: 'hcl',
        icon: '🔄',
        content: `# Disaster Recovery Automation — DORA Compliance
# RTO: 1 hour, RPO: 5 minutes

# Multi-region deployment for DR
resource "aws_db_instance" "ledger_dr" {
  count = var.enable_dr ? 1 : 0

  identifier     = "{{.Project.Name}}-ledger-dr"
  engine         = "aurora-postgresql"
  engine_version = "15.4"
  instance_class = "db.r6g.large"

  # Cross-region read replica for DR
  replicate_source_db = aws_rds_cluster.postgresql.id

  storage_encrypted = true
  kms_key_id        = aws_kms_key.rds.arn

  backup_retention_period = 30
  preferred_backup_window = "03:00-04:00"

  tags = merge(var.common_tags, {
    Role = "DR-Replica"
    RTO  = "1h"
    RPO  = "5m"
  })
}

# Automated failover Lambda
resource "aws_lambda_function" "dr_failover" {
  count = var.enable_dr ? 1 : 0

  filename         = "lambda/dr_failover.zip"
  function_name    = "{{.Project.Name}}-dr-failover"
  role             = aws_iam_role.dr_failover.arn
  handler          = "failover.handler"
  runtime          = "python3.11"
  timeout          = 300

  environment {
    variables = {
      PRIMARY_CLUSTER = aws_rds_cluster.postgresql.id
      DR_CLUSTER      = aws_db_instance.ledger_dr[0].id
      SNS_TOPIC_ARN   = aws_sns_topic.dr_alerts.arn
    }
  }

  tags = var.common_tags
}

# CloudWatch alarm for automatic failover trigger
resource "aws_cloudwatch_metric_alarm" "primary_health" {
  count = var.enable_dr ? 1 : 0

  alarm_name          = "{{.Project.Name}}-primary-unhealthy"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = "2"
  metric_name         = "DatabaseConnections"
  namespace           = "AWS/RDS"
  period              = "60"
  statistic           = "Average"
  threshold           = "0"
  alarm_actions       = [aws_lambda_function.dr_failover[0].arn]

  dimensions = {
    DBClusterIdentifier = aws_rds_cluster.postgresql.id
  }

  tags = var.common_tags
}

# SNS topic for DR alerts
resource "aws_sns_topic" "dr_alerts" {
  count = var.enable_dr ? 1 : 0

  name = "{{.Project.Name}}-dr-alerts"
  tags = var.common_tags
}`
